function runningTotals(rows){
  // rows: [{day, amount}], already ordered by day
  const out = [];
  for (let i = 0; i < rows.length; i++){
    let sum = 0;
    for (let j = 0; j < rows.length; j++){
      if (rows[j].day <= rows[i].day) sum += rows[j].amount;
    }
    out.push(sum);
  }
  return out;
}

